function getOrders(user, cb) { setTimeout(() => cb(null, ['o1', 'o2', 'o3']), 5); }
function summarize(user, orders, cb) {
  setTimeout(() => cb(null, user.name + ' has ' + orders.length + ' orders'), 5);
}

function onSummary(err, summary) {
  if (err) return console.log('failed:', err.message);
  console.log(summary);
}
function onOrders(user) {
  return (err, orders) => {
    if (err) return console.log('failed:', err.message);
    summarize(user, orders, onSummary);
  };
}
function onUser(err, user) {
  if (err) return console.log('failed:', err.message);
  getOrders(user, onOrders(user));
